const PF_CFG={url:'https://tikjmiyrhkcjrxjylmqb.supabase.co',key:'sb_publishable_clr5P9USk7b63MajJmmr9A_Iz0wi_0F',version:'2026.08.16-preventive1'};
const PF_SESSION='fleet_mvp_session_v2';
function pfSession(){try{return JSON.parse(localStorage.getItem(PF_SESSION)||'null')}catch{return null}}
function pfSaveSession(s){if(s)localStorage.setItem(PF_SESSION,JSON.stringify(s))}
async function pfRefresh(){const s=pfSession();if(!s?.refresh_token)throw new Error('Сессия истекла. Войдите снова.');const r=await fetch(`${PF_CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:PF_CFG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw new Error(d.message||d.msg||'Сессия истекла. Войдите снова.');d.obtained_at=Date.now();pfSaveSession(d);return d}
async function pfRpc(name,params={},retry=true){let s=pfSession();if(!s?.access_token)throw new Error('Нужно войти в систему.');let r=await fetch(`${PF_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:PF_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)});if(r.status===401&&retry){await pfRefresh();return pfRpc(name,params,false)}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||x.error||x.hint||`HTTP ${r.status}`)}const t=await r.text();return t?JSON.parse(t):null}
function pfEsc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function pfDate(v){if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)}
function pfToast(text,type=''){let h=document.querySelector('.toast-host');if(!h){h=document.createElement('div');h.className='toast-host';document.body.appendChild(h)}const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=text;h.appendChild(e);setTimeout(()=>e.remove(),3800)}
function pfRefreshPage(){const b=document.createElement('button');b.type='button';b.hidden=true;b.dataset.action='refresh';document.body.appendChild(b);b.click();queueMicrotask(()=>b.remove())}
function pfItem(x){const facts=[];if(x.root_cause)facts.push(`Причина: ${pfEsc(x.root_cause)}`);if(x.repair_closed_at)facts.push(`ремонт закрыт ${pfEsc(pfDate(x.repair_closed_at))}`);return `<div class="card" style="padding:12px" data-pf-item="${pfEsc(x.id)}"><div style="display:flex;gap:12px;align-items:flex-start;justify-content:space-between"><div style="min-width:0;flex:1"><div style="font-weight:800">${pfEsc(x.vehicle_label||'Техника')}</div><div style="margin-top:5px;line-height:1.45">${pfEsc(x.action_text)}</div>${facts.length?`<div class="muted small" style="margin-top:5px">${facts.join(' · ')}</div>`:''}</div><span class="badge warning">Открыта</span></div><div class="action-row" style="margin-top:10px"><button type="button" class="primary-btn" data-pf-complete="${pfEsc(x.id)}">Выполнено</button><button type="button" class="ghost-btn" data-pf-cancel="${pfEsc(x.id)}">Отменить</button></div></div>`}
function pfSection(d){const items=d.items||[];const s=document.createElement('section');s.className='section';s.dataset.pfSection=PF_CFG.version;s.innerHTML=`<div class="section-head"><div><h2>Профилактика после ремонта</h2><div class="muted small">То, что нужно сделать после выявленной предотвратимой причины.</div></div><span class="badge warning">${items.length}</span></div><div style="display:grid;gap:8px;margin-top:10px">${items.map(pfItem).join('')}</div>`;return s}
async function pfDecorate(){const main=document.querySelector('.main');if(!main||main.querySelector('[data-pf-section]'))return;const title=document.querySelector('.page-title')?.textContent?.trim();if(title!=='ТО и ремонт')return;let d;try{d=await pfRpc('get_repair_preventive_followups_ui')}catch{return}if(!main.isConnected||Number(d?.open_count||0)===0||main.querySelector('[data-pf-section]'))return;const section=pfSection(d),head=main.querySelector('.page-head');if(head)head.after(section);else main.prepend(section)}
async function pfComplete(button){const id=button.dataset.pfComplete;if(!id)return;const dialog=window.fleetUxDialog;const ok=dialog?await dialog({title:'Профилактика выполнена?',body:'Задача уйдёт из открытых, а факт выполнения останется в истории.',confirmLabel:'Отметить выполненной'}):window.confirm('Отметить профилактическую задачу выполненной?');if(!ok)return;button.disabled=true;try{await pfRpc('complete_repair_preventive_followup',{p_followup_id:id});pfToast('Профилактическая задача выполнена.','success');pfRefreshPage()}catch(e){pfToast(e.message||'Не удалось закрыть задачу.','error');button.disabled=false}}
async function pfCancel(button){const id=button.dataset.pfCancel;if(!id)return;const prompt=window.fleetUxPrompt;const reason=prompt?await prompt({title:'Отменить профилактическую задачу?',body:'Задача исчезнет из открытых, но причина отмены останется в истории.',label:'Почему отменяем',placeholder:'Например: действие заменено новым регламентом ТО',required:true,maxLength:300,confirmLabel:'Отменить задачу',danger:true}):window.prompt('Причина отмены:');if(!String(reason||'').trim())return;button.disabled=true;try{await pfRpc('cancel_repair_preventive_followup',{p_followup_id:id,p_reason:String(reason).trim()});pfToast('Профилактическая задача отменена.','success');pfRefreshPage()}catch(e){pfToast(e.message||'Не удалось отменить задачу.','error');button.disabled=false}}
document.addEventListener('click',e=>{const done=e.target.closest('[data-pf-complete]');if(done){e.preventDefault();e.stopImmediatePropagation();pfComplete(done);return}const cancel=e.target.closest('[data-pf-cancel]');if(cancel){e.preventDefault();e.stopImmediatePropagation();pfCancel(cancel)}},true);
let pfQueued=false;function pfSchedule(){if(pfQueued)return;pfQueued=true;queueMicrotask(()=>{pfQueued=false;pfDecorate()})}new MutationObserver(pfSchedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('fleet:role-ux-ready',pfSchedule);pfSchedule();
